import { useEffect, useState } from "react";
import api from "./api";

export default function CodeEditorPage() {
  const userId = localStorage.getItem("userId");

  const [language, setLanguage] = useState("python");
  const [code, setCode] = useState("");
  const [fontSize, setFontSize] = useState(16);

  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(null);
  const [level, setLevel] = useState(null);

  const [userInput, setUserInput] = useState("");   // ✅ NEW
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);

  /* ================= LOAD LEVELS ================= */
  useEffect(() => {
    async function loadLevels() {
      const res = await api.get(`/levels/${userId}`);
      setLevels(res.data.levels);
      setCurrentLevel(res.data.currentLevel);
    }
    loadLevels();
  }, [userId]);

  /* ================= LOAD CURRENT LEVEL ================= */
  useEffect(() => {
    if (!currentLevel) return;

    async function loadCurrentLevel() {
      const res = await api.get(`/level/${userId}`);
      setLevel(res.data.level);
      setUserInput(""); // reset input on level change
      setCode("");
      setOutput("");
    }
    loadCurrentLevel();
  }, [currentLevel, userId]);

  /* ================= RUN ================= */
  const handleRun = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language,
        stdin: userInput,   // ✅ send user input
        userId,
      });

      setOutput(res.data.userOutput);
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  /* ================= SUBMIT ================= */
  const handleSubmit = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language,
        stdin: userInput,   // ✅ send user input
        userId,
      });

      setOutput(res.data.userOutput);

      if (res.data.success) {
        alert("✅ Correct! Next level unlocked");
        window.location.reload();
      } else {
        alert("❌ Wrong Answer");
      }
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  if (!level) return <h2 style={{ color: "white" }}>Loading...</h2>;

  return (
    <div style={styles.app}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.logo}>DailyCode</h1>
      </div>

      <div style={styles.body}>
        {/* SIDEBAR */}
        <div style={styles.sidebar}>
          <h3>Levels</h3>
          {levels.map((l) => (
            <button
              key={l.level_no}
              style={{
                ...styles.levelBtn,
                ...(l.level_no === currentLevel
                  ? styles.current
                  : l.level_no < currentLevel
                  ? styles.completed
                  : styles.locked),
              }}
              disabled={l.level_no > currentLevel}
            >
              Level {l.level_no}
            </button>
          ))}
        </div>

        {/* MAIN */}
        <div style={styles.main}>
          <h2 style={styles.levelTitle}>
            Level {level.level_no}: {level.title}
          </h2>

          <p>{level.description}</p>

          {/* CODE EDITOR */}
          <textarea
            value={code}
            onChange={(e) => setCode(e.target.value)}
            placeholder={`Write your ${language} code here...`}
            style={styles.editor}
          />

          {/* ACTIONS */}
          <div style={styles.actions}>
            <button style={styles.runBtn} onClick={handleRun}>▶ Run</button>
            <button style={styles.submitBtn} onClick={handleSubmit}>✔ Submit</button>
          </div>

          {/* INPUT / OUTPUT */}
          <div style={styles.outputs}>
            <div style={styles.box}>
              <h4>Sample Input</h4>
              <pre>{level.input_data || "N/A"}</pre>
            </div>

            <div style={styles.box}>
              <h4>Your Input (optional)</h4>
              <textarea
                value={userInput}
                onChange={(e) => setUserInput(e.target.value)}
                style={styles.userInput}
                placeholder="Enter input here"
              />
            </div>

            <div style={styles.box}>
              <h4>Expected Output</h4>
              <pre>{level.expected_output}</pre>
            </div>

            <div style={styles.box}>
              <h4>Your Output</h4>
              <pre>{loading ? "Running..." : output || "/* Output here */"}</pre>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ================= STYLES ================= */
const styles = {
  app: { background: "#0f172a", minHeight: "100vh", color: "white" },
  header: { padding: 15, background: "#1e293b" },
  logo: { color: "#38bdf8" },
  body: { display: "flex", padding: 20, gap: 20 },
  sidebar: { width: 200 },
  levelBtn: { width: "100%", marginBottom: 8, padding: 10 },
  current: { background: "#4caf50" },
  completed: { background: "#2196f3" },
  locked: { background: "#475569" },
  main: { flex: 1, background: "#1e293b", padding: 20, borderRadius: 10 },
  editor: {
    width: "100%",
    height: 250,
    background: "#0f172a",
    color: "white",
    border: "1px solid #334155",
    borderRadius: 6,
    padding: 10,
    fontFamily: "monospace",
  },
  actions: { marginTop: 10 },
  runBtn: { background: "#3b82f6", padding: "8px 16px", color: "white" },
  submitBtn: { background: "#4caf50", padding: "8px 16px", marginLeft: 10 },
  outputs: { marginTop: 20, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 15 },
  box: { background: "#334155", padding: 10, borderRadius: 6 },
  userInput: {
    width: "100%",
    height: 60,
    background: "#0f172a",
    color: "white",
    border: "1px solid #475569",
    padding: 6,
  },
};
